from author import add, save
add(1,'''import { realpath } from 'node:fs/promises';
console.log({ executable:await realpath(process.execPath), node:process.version, v8:process.versions.v8, platform:process.platform, arch:process.arch });
if(process.versions.node!=='26.13.1') throw Error('Select the pinned course runtime: 26.13.1');''','Prints the actual executable and pinned runtime. A different version fails explicitly.','Use fnm or nvm to select the .node-version value, then compare command resolution. The application verifies the runtime rather than changing a machine-wide installation.')
add(2,'''import {assert,spawnNode} from '../../shared/lab.mjs';
for(const args of [['--eval','2 + 3'],['--print','2 + 3'],['--check','main.mjs'],['main.mjs'],['--check','bad.mjs']]) {
 const r=await spawnNode(args); console.log({args,...r}); assert.equal(r.code,args.includes('bad.mjs')?1:0);
}''','eval has no result output; print writes 5; main prints a greeting; the intentionally invalid fixture fails parsing.',files={'main.mjs':"console.log('Hello, Node.js!');",'bad.mjs':"const x = ;"})
add(3,'''import {assert,spawnNode} from '../../shared/lab.mjs';
const run=await spawnNode(['src/add.js']);console.log(run.stdout.trim());assert.equal(run.stdout.trim(),'5');
const tests=await spawnNode(['--test','test/add.test.js']);console.log(tests.stdout);assert.equal(tests.code,0);''','The application prints 5 and its addition test passes.',files={'src/add.js':"export const add=(a,b)=>a+b; console.log(add(2,3));",'test/add.test.js':"import test from 'node:test'; import assert from 'node:assert/strict'; import {add} from '../src/add.js'; test('adds',()=>assert.equal(add(2,3),5));"})
add(4,'''import {assert,spawnNode} from '../../shared/lab.mjs';
for(const PORT of ['3000','0','not-a-port']) {const r=await spawnNode(['--env-file=fixture.env','config.mjs'],{env:{...process.env,PORT}});console.log({PORT,...r});assert.equal(r.code,PORT==='3000'?0:1);}''','Valid configuration prints public fields. Invalid ports fail without exposing the fixture secret.',files={'fixture.env':'PORT=3000\nDEBUG=false\nAPI_KEY=public-lab-fixture','config.mjs':"const port=Number(process.env.PORT??3000); if(!Number.isInteger(port)||port<1||port>65535)throw Error('Invalid PORT');const d=process.env.DEBUG??'false';if(!['true','false'].includes(d)||!process.env.API_KEY?.trim())throw Error('Invalid configuration');console.log({port,debug:d==='true'});"})
add(5,'''import {assert,spawnNode} from '../../shared/lab.mjs';
for(const args of [['--input','demo'],['--help'],['--unknown']]){const r=await spawnNode(['cli.mjs',...args]);console.log({args,...r});assert.equal(r.code,args.includes('--unknown')?1:0);}''','Valid input is JSON on stdout; an invalid flag produces stderr and a nonzero exit.',files={'cli.mjs':"import {parseArgs} from 'node:util';try{const {values}=parseArgs({options:{input:{type:'string'},help:{type:'boolean'}}});if(values.help)console.log('Usage: --input NAME');else{if(!values.input)throw Error('Missing input');console.log(JSON.stringify({input:values.input}));}}catch(e){console.error(e.message);process.exitCode=1;}"})
add(6,'''import {assert,spawnNode} from '../../shared/lab.mjs';
const yes=await spawnNode(['ask.mjs','--yes']);const piped=await spawnNode(['ask.mjs'],{input:'y\\n'});console.log(yes,piped);assert.equal(yes.code,0);assert.equal(piped.code,1);''','--yes confirms; piped input is deliberately rejected instead of hanging for a TTY.',files={'ask.mjs':"import {createInterface} from 'node:readline/promises';if(process.argv.includes('--yes'))console.log('Confirmed');else if(!process.stdin.isTTY){console.error('Noninteractive: use --yes');process.exitCode=1;}else{const rl=createInterface({input:process.stdin,output:process.stdout});const abort=new AbortController();rl.on('SIGINT',()=>abort.abort());try{console.log(/^y(es)?$/i.test(await rl.question('Continue? [y/N] ',{signal:abort.signal}))?'Confirmed':'Cancelled');}catch(e){if(e.name!=='AbortError')throw e;console.log('Cancelled');}finally{rl.close();}}"})
add(7,'''import {spawn} from 'node:child_process';
const child=spawn(process.execPath,['--watch','main.mjs'],{stdio:'inherit'});child.on('exit',code=>process.exitCode=code??0);''','Edit message.mjs in another editor: watch mode restarts and prints the changed message. Stop with Ctrl+C.','Watch mode is intentionally interactive and is excluded from the unattended validator. In-memory state resets on each restart.',files={'main.mjs':"import {message} from './message.mjs';console.log(message);",'message.mjs':"export const message='Hello, Node.js!';"},mode='interactive')
add(8,'''import assert from 'node:assert/strict';
function counter(){let n=0;return()=>++n;}const a=counter(),b=counter();const values=[a(),a(),b()];console.log(values);assert.deepEqual(values,[1,2,1]);
const wrong=[],right=[];for(var i=0;i<3;i++)wrong.push(()=>i);for(let j=0;j<3;j++)right.push(()=>j);console.log(wrong.map(f=>f()),right.map(f=>f()));''','Independent counters produce [1,2,1]; var closures see 3,3,3 and let closures see 0,1,2.')
add(9,'''import assert from 'node:assert/strict';
const original={server:{port:0},nested:{enabled:true}};const configured={...original,server:{...original.server,port:original.server.port??3000,tls:original.server.tls??false}};console.log(original,configured);assert.equal(configured.server.port,0);assert.equal(original.server.tls,undefined);const shallow={...original};shallow.nested.enabled=false;assert.equal(original.nested.enabled,false);console.log('shallow copy shares nested object');''','Nullish defaults preserve port 0; copied nested state still shares identity unless copied explicitly.')
add(10,'''import assert from 'node:assert/strict';
class Inventory{#count=0;add(n=1){this.#count+=n;return this.#count;}}
const stock=new Inventory(),loose=stock.add;assert.throws(()=>loose(),TypeError);console.log('TypeError for lost receiver');console.log(stock.add.bind(stock)(),(()=>stock.add())());''','An unbound method fails; binding or calling through its receiver produces 1 then 2.')
add(11,'''import assert from 'node:assert/strict';
const users=new Map([[7,{name:'Luis'}]]),meta=new WeakMap();const user=users.get(7);meta.set(user,{selected:true});console.log([...new Set([1,1,2])],user.name,meta.get(user),new Set([{},{}]).size);assert.equal(new Set([{},{}]).size,2);''','Set removes repeated primitives; distinct objects remain distinct; WeakMap stores non-enumerable object metadata.')
add(12,'''import assert from 'node:assert/strict';
let produced=0,cleaned=false;function* range(n){try{for(let i=0;i<n;i++){produced++;yield i;}}finally{cleaned=true;}}
const first=[];for(const n of range(1_000_000)){first.push(n);if(first.length===10)break;}console.log({first,produced,cleaned});assert.equal(produced,10);assert.equal(cleaned,true);''','Only ten values are produced; breaking the loop executes generator cleanup.')
add(13,'''import assert from 'node:assert/strict';
const row={id:9007199254740993n,createdAt:new Date('2026-01-01T00:00:00Z')};assert.throws(()=>JSON.stringify(row),TypeError);const json=JSON.stringify({id:String(row.id),createdAt:row.createdAt.toISOString()});const parsed=JSON.parse(json);const restored={id:BigInt(parsed.id),createdAt:new Date(parsed.createdAt)};console.log(json,restored.id===row.id);assert.equal(restored.id,row.id);''','A decimal string preserves an integer beyond Number.MAX_SAFE_INTEGER; dates need explicit reconstruction.')
add(14,r'''import assert from 'node:assert/strict';
const valid=s=>/^[$_\p{ID_Start}][$\u200C\u200D\p{ID_Continue}]*$/u.test(s.normalize('NFC'));
const a='café',b='cafe\u0301',face='😀';console.log(a===b,a.normalize('NFC')===b.normalize('NFC'));console.log(face.length,[...face].length,Buffer.byteLength(face));console.log(valid('café'),valid('😀'));assert.equal(a.normalize('NFC'),b.normalize('NFC'));''','Normalization equates canonical text; the emoji occupies 2 UTF-16 units, 1 code point, and 4 UTF-8 bytes.')
add(15,'''const fmt=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',hour:'2-digit',minute:'2-digit',hour12:false});console.log(['2026-03-29T00:30:00Z','2026-03-29T01:30:00Z'].map(t=>fmt.format(new Date(t))));for(const [locale,currency] of [['es-ES','EUR'],['en-US','USD']])console.log(new Intl.NumberFormat(locale,{style:'currency',currency}).format(1234.5));''','Madrid jumps from 01:30 to 03:30. Currency formatting depends on locale/ICU; it does not convert currency.')
add(16,'''import {createServer} from 'node:http';import {listen,close,delay} from '../../shared/lab.mjs';
const server=createServer(async(req,res)=>{try{if(req.url==='/io')await delay(100);else{const end=performance.now()+100;while(performance.now()<end){}}res.end('done');}catch{res.writeHead(500);res.end();}});const base=await listen(server);
try{for(const route of ['/io','/cpu']){const start=performance.now();await Promise.all([fetch(base+route).then(r=>r.text()),fetch(base+route).then(r=>r.text())]);console.log(route,Math.round(performance.now()-start),'measured ms');}}finally{await close(server);}''','Concurrent I/O waits overlap; synchronous CPU work serializes the server. Printed durations are measurements, not fixed timing promises.')
add(17,'''import {readFile} from 'node:fs';
setTimeout(()=>console.log('outer timeout'),0);setImmediate(()=>console.log('outer immediate'));readFile(new URL(import.meta.url),()=>{setTimeout(()=>console.log('I/O timeout'),0);setImmediate(()=>console.log('I/O immediate'));});''','Inside the I/O callback immediate precedes timeout. Top-level timeout/immediate order is deliberately not asserted.')
add(18,'''import {assert,spawnNode} from '../../shared/lab.mjs';
for(const file of ['order.cjs','order.mjs']){const r=await spawnNode([file]);console.log(file,r.stdout);assert.equal(r.code,0);}''','CJS prints sync,nextTick,promise,microtask; ESM prints sync,promise,microtask,nextTick for this top-level fixture.',files={name:"console.log('sync');process.nextTick(()=>console.log('nextTick'));Promise.resolve().then(()=>console.log('promise'));queueMicrotask(()=>console.log('microtask'));" for name in ['order.cjs','order.mjs']})
add(19,'''import {scrypt} from 'node:crypto';import {promisify} from 'node:util';import {assert,spawnNode} from '../../shared/lab.mjs';
for(const size of ['2','8']){const r=await spawnNode(['pool.mjs'],{env:{...process.env,UV_THREADPOOL_SIZE:size}});console.log('threads',size,r.stdout);assert.equal(r.code,0);}''','Each fresh process measures eight crypto jobs sharing libuv resources; more threads are not guaranteed to improve elapsed time.',files={'pool.mjs':"import {readFile} from 'node:fs/promises';import {scrypt} from 'node:crypto';import {promisify} from 'node:util';const run=promisify(scrypt);const start=performance.now();await Promise.all([...Array.from({length:8},()=>run('fixture','salt',64)),readFile(new URL(import.meta.url))]);console.log('elapsed ms:',Math.round(performance.now()-start));"})
add(20,'''import {assert,delay} from '../../shared/lab.mjs';const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30);try{await delay(1000,null,{signal:controller.signal});assert.fail('must cancel');}catch(e){assert.equal(e.name,'AbortError');console.log(e.name);}finally{clearTimeout(timer);}''','AbortError is observed; manually owned timers are cleared.')
add(21,'''import {createServer} from 'node:http';import {listen,close} from '../../shared/lab.mjs';const timer=setInterval(()=>{},1000);const server=createServer((q,s)=>s.end('ok'));await listen(server);console.log(process.getActiveResourcesInfo());clearInterval(timer);await close(server);console.log('closed; natural process exit');''','Active timer/server resources appear before cleanup; the process then exits naturally. Resource names vary by platform.')
